-- Only compilation coverage for satellite/cancellation full bodies; not a payer execution fixture.
CREATE TABLE public.spin_bonus_pools("id" uuid,"club_id" uuid,"balance" numeric(12,2),"total_deposited" numeric(12,2),"total_drawn" numeric(12,2),"spin_count" integer,"bonus_count" integer,"created_at" timestamp with time zone,"updated_at" timestamp with time zone,"seeded_amount" numeric,"ceiling_amount" numeric,"highest_stake" numeric,"surplus_returned" numeric,"is_active" boolean,"owner_kind" text,"offered_max_stake" numeric,"activated_at" timestamp with time zone,"activated_by" uuid,"deactivated_at" timestamp with time zone,"seed_source_wallet" text,"seed_returned_at" timestamp with time zone,"seed_returned_amount" numeric,"required_seed_at_activation" numeric);
